// PrismaClient is the main JavaScript/TypeScript object generated by Prisma that lets you interact with your database.
import { PrismaClient } from "@/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";  

const connectionString = `${process.env.DATABASE_URL}`;

if (!connectionString) {
  throw new Error("DATABASE_URL is not defined in environment variables");
}

if (!globalThis.prisma) {
    const adapter = new PrismaPg({ connectionString });
    globalThis.prisma = new PrismaClient({            // 'globalThis' is a global object in JavaScript that persists across module reloads in Node.js.
        adapter,
        log: process.env.NODE_ENV === 'development' 
            // ? ['query', 'error', 'warn']              // The "query" option tells Prisma: "Print every SQL query on console that gets executed."
            ? ['error', 'warn']
            : ['error'],
    });
}

export const db = globalThis.prisma;